    """
    Pattern: Find the main cluster of non-background pixels.
    Replace all isolated foreground pixels with values from the cluster pattern.
    """
    if not grid or not grid[0]:
        return grid

    # Find background (most common value)
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    background = max(counts, key=counts.get)

    # Find all non-background positions
    non_bg = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                non_bg.append((r, c, grid[r][c]))

    # Find the largest cluster (source pattern)
    visited = set()
    clusters = []

    for r, c, val in non_bg:
        if (r, c) in visited:
            continue

        cluster = {}
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            key = (cr, cc)
            if key not in visited:
                visited.add(key)
                cluster[key] = grid[cr][cc]

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] != background and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))

        if cluster:
            clusters.append((cluster, len(cluster)))

    # Source cluster is the largest one
    if clusters:
        source_cluster, _ = max(clusters, key=lambda x: x[1])

        # Build pattern values list from source cluster
        pattern_values = list(source_cluster.values())

        # Build output - background stays, non-bg positions use pattern values
        output = [[background] * len(grid[0]) for _ in range(len(grid))]

